/**
 * Archives every live issue in the request that this actor may archive on
 * its own. Unknown ids, another organization's ids, and issues that are
 * already archived are skipped and left untouched. A duplicate counts once.
 * Permission is checked for every remaining issue before any row is written;
 * one denial rejects the call with nothing archived and no events published.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const orderedIds: IssueId[] = [];
  const seen = new Set<IssueId>();
  for (const issueId of input.issueIds) {
    if (seen.has(issueId)) continue;
    seen.add(issueId);
    orderedIds.push(issueId);
  }

  const found = await issueRepo.findIssuesByIds(input.orgId, orderedIds);
  const byId = new Map(found.map((issue) => [issue.id, issue]));

  const skipped: IssueId[] = [];
  const pending: Issue[] = [];
  for (const issueId of orderedIds) {
    const issue = byId.get(issueId);
    if (issue === undefined || isArchived(issue)) {
      skipped.push(issueId);
      continue;
    }
    pending.push(issue);
  }

  for (const issue of pending) {
    assertCan(actor, "issue:archive", issueResource(issue));
  }

  const archived: IssueId[] = [];
  for (const issue of pending) {
    const row = await issueRepo.archiveIssue(input.orgId, issue.id);
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
    archived.push(row.id);
  }

  return { archived, skipped };
}

